// Pure helpers for the markdown state files under .vibe-code/ (goals, plans).

const escapeRegExp = (value: string): string => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/**
 * 입력의 줄바꿈 방식. 첫 줄바꿈이 `\r\n` 이면 CRLF, 그 밖에는(줄바꿈이 없을 때도) LF 다.
 * 혼합 줄바꿈 파일은 첫 줄바꿈을 따른다 — VS Code 의 `TextDocument.eol` 과 같은 규칙.
 */
export function detectEol(text: string): "\n" | "\r\n" {
	const first = text.indexOf("\n");
	return first > 0 && text[first - 1] === "\r" ? "\r\n" : "\n";
}

/** CRLF 를 LF 로 바꾼 사본. 아래 파서들은 모두 이 형태만 본다. */
export function normalizeEol(text: string): string {
	return text.includes("\r") ? text.replace(/\r\n/g, "\n") : text;
}

/** 정규화된(LF) 텍스트를 원래 줄바꿈으로 되돌린다. 정규화하지 않은 텍스트에 쓰면 `\r\r\n` 이 된다. */
export function restoreEol(normalized: string, eol: "\n" | "\r\n"): string {
	return eol === "\r\n" ? normalized.replace(/\n/g, "\r\n") : normalized;
}

function sectionHeadRe(name: string): RegExp {
	return new RegExp("((?:^|\\n)## " + escapeRegExp(name) + "\\n)");
}

/** Whether the text has a `## <name>` section. Parser and lint share this one check. */
export function hasSection(text: string, name: string): boolean {
	return sectionHeadRe(name).test(normalizeEol(text));
}

/** Value of a `label: value` line, trimmed; `fallback` when absent. */
export function matchLine(text: string, label: string, fallback = ""): string {
	const match = normalizeEol(text).match(new RegExp("^" + escapeRegExp(label) + ":\\s*(.+)$", "m"));
	return (match?.[1] || fallback).trim();
}

/** Title from a `# <prefix>: <title>` heading. */
export function headingTitle(text: string, prefix: string, fallback: string): string {
	const match = normalizeEol(text).match(new RegExp("^#\\s*" + escapeRegExp(prefix) + ":\\s*(.+)$", "m"));
	return (match?.[1] || fallback).trim();
}

/** Body of a `## <name>` section up to the next `## ` heading, trimmed. */
export function section(text: string, name: string): string {
	const re = new RegExp("(?:^|\\n)## " + escapeRegExp(name) + "\\n([\\s\\S]*?)(?=\\n## |$)");
	return (normalizeEol(text).match(re)?.[1] || "").trim();
}

/** Body of a `### <name>` sub-section up to the next `### ` or `## ` heading, trimmed. */
export function subsection(text: string, name: string): string {
	const re = new RegExp("(?:^|\\n)### " + escapeRegExp(name) + "\\n([\\s\\S]*?)(?=\\n### |\\n## |$)");
	return (normalizeEol(text).match(re)?.[1] || "").trim();
}

/**
 * Replace the body of a `## <name>` section with `lines`; unchanged when the section is missing.
 * 입력의 줄바꿈을 그대로 돌려준다.
 */
export function writeSection(text: string, name: string, lines: string[]): string {
	const eol = detectEol(text);
	const body = normalizeEol(text);
	const re = new RegExp(sectionHeadRe(name).source + "([\\s\\S]*?)(?=\\n## |$)");
	if (!re.test(body)) return text;
	return restoreEol(
		body.replace(re, (_match, head: string) => head + (lines.length > 0 ? lines.join("\n") + "\n" : "\n")),
		eol,
	);
}

/**
 * Lines of a `## <name>` section exactly as written — indentation and non-checklist notes kept.
 * An empty or missing section is `[]`, never `[""]`. Pair with `writeSection` to edit a section
 * without dropping the lines the editor does not care about.
 */
export function sectionLines(text: string, name: string): string[] {
	const body = section(text, name);
	return body === "" ? [] : body.split("\n");
}

/** Trimmed, non-empty lines of a block. */
export function lines(block: string): string[] {
	return block
		.split(/\r?\n/)
		.map((line) => line.trim())
		.filter(Boolean);
}

/** Checklist lines (`- [ ]` / `- [x]`) of a block. */
export function taskLines(block: string): string[] {
	return lines(block).filter((line) => line.startsWith("- ["));
}

export function isDoneTask(line: string): boolean {
	return /^- \[[xX]\]/.test(line);
}

/** Checklist line without its `- [ ] ` prefix. */
export function stripTask(line: string): string {
	return line.replace(/^- \[(?: |x|X)\]\s*/, "");
}

export interface CheckCount {
	done: number;
	total: number;
}

/** Counts every checklist item in the text. */
export function countChecks(text: string): CheckCount {
	const checks = [...normalizeEol(text).matchAll(/^- \[( |x|X)\] /gm)];
	return { done: checks.filter((m) => m[1].toLowerCase() === "x").length, total: checks.length };
}

export function progressLabel(count: CheckCount, empty: string): string {
	return count.total > 0 ? `${count.done}/${count.total}` : empty;
}

/**
 * Set a `label: value` metadata line. Missing lines are inserted after `마지막 갱신:`,
 * or after `작성일:` when there is no `마지막 갱신:` line. 입력의 줄바꿈을 그대로 돌려준다.
 */
export function setLine(text: string, label: string, value: string): string {
	const eol = detectEol(text);
	const body = normalizeEol(text);
	const re = new RegExp("^" + escapeRegExp(label) + ":\\s*.+$", "m");
	const line = label + ": " + value;
	const next = re.test(body)
		? body.replace(re, () => line)
		: /^마지막 갱신:\s*.+$/m.test(body)
			? body.replace(/^마지막 갱신:\s*.+$/m, (m) => m + "\n" + line)
			: body.replace(/^작성일:\s*.+$/m, (m) => m + "\n" + line);
	return restoreEol(next, eol);
}

/** Update `상태:` (when given) and bump `마지막 갱신:` to `stamp`. 입력의 줄바꿈을 그대로 돌려준다. */
export function touchPlan(text: string, status: string | null, stamp: string): string {
	const eol = detectEol(text);
	let next = normalizeEol(text);
	if (status) {
		if (/^상태:\s*.+$/m.test(next)) next = next.replace(/^상태:\s*.+$/m, () => "상태: " + status);
		else next = next.replace(/^# .+$/m, (m) => m + "\n\n상태: " + status);
	}
	if (/^마지막 갱신:\s*.+$/m.test(next)) next = next.replace(/^마지막 갱신:\s*.+$/m, () => "마지막 갱신: " + stamp);
	else if (/^작성일:\s*.+$/m.test(next)) next = next.replace(/^작성일:\s*.+$/m, (m) => m + "\n마지막 갱신: " + stamp);
	return restoreEol(next, eol);
}

const PRIORITY_RANK: Record<string, number> = { P0: 0, P1: 1, P2: 2, P3: 3 };

/** `P0` sorts first; unknown priorities last. */
export function priorityRank(priority: string | undefined): number {
	const value = String(priority || "P2").trim().toUpperCase();
	return PRIORITY_RANK[value] ?? 9;
}

// --- line-level editing (used by the plan CodeLens commands) ---------------------------------

/** Name of the `## ` section that contains `lineIndex`, or "" when above the first heading. */
export function sectionOfLine(text: string, lineIndex: number): string {
	const all = text.split(/\r?\n/);
	for (let i = Math.min(lineIndex, all.length - 1); i >= 0; i--) {
		const m = all[i].match(/^## (.+)$/);
		if (m) return m[1].trim();
		if (/^# /.test(all[i])) return "";
	}
	return "";
}

export function isTaskLine(line: string): boolean {
	return /^- \[( |x|X)\] /.test(line);
}

/** Flip `- [ ]` <-> `- [x]` on one line; other lines are returned unchanged. 줄바꿈은 보존한다. */
export function toggleCheckbox(text: string, lineIndex: number): string {
	const eol = detectEol(text);
	const all = normalizeEol(text).split("\n");
	const line = all[lineIndex];
	if (line === undefined || !isTaskLine(line)) return text;
	all[lineIndex] = isDoneTask(line) ? line.replace(/^- \[[xX]\]/, "- [ ]") : line.replace(/^- \[ \]/, "- [x]");
	return restoreEol(all.join("\n"), eol);
}

/**
 * Remove the task at `lineIndex` and append it (optionally transformed) to the end of
 * `## targetSection`. Returns null when the line is not a task or the section is missing.
 * 줄바꿈은 보존한다.
 */
export function moveTaskToSection(text: string, lineIndex: number, targetSection: string, transform: (line: string) => string = (l) => l): string | null {
	const eol = detectEol(text);
	const all = normalizeEol(text).split("\n");
	const line = all[lineIndex];
	if (line === undefined || !isTaskLine(line.trim())) return null;
	if (!hasSection(all.join("\n"), targetSection)) return null;
	all.splice(lineIndex, 1);
	const without = all.join("\n");
	// 대상 섹션은 원본 줄 그대로 다시 쓴다 — lines() 로 재조립하면 들여쓰기와 메모 줄이 사라진다.
	return restoreEol(writeSection(without, targetSection, [...sectionLines(without, targetSection), transform(line.trim())]), eol);
}
import { describe, expect, it } from "vitest";
import {
	countChecks,
	detectEol,
	hasSection,
	headingTitle,
	lines,
	matchLine,
	moveTaskToSection,
	normalizeEol,
	priorityRank,
	section,
	sectionLines,
	setLine,
	subsection,
	taskLines,
	toggleCheckbox,
	touchPlan,
	writeSection,
} from "../../src/util/markdown";
import { openPlanItems, planTemplate } from "../../src/features/plans";
import { goalTemplate, parseGoal } from "../../src/features/goals";
import { lintGoal, lintPlan } from "../../src/features/goal-lint";

const STAMP = "2026-09-22 10:00:00 KST";

describe("section parsing", () => {
	const plan = planTemplate("테스트 목표", "current-plan.md", STAMP);

	it("reads whole multi-line sections, not just the first line", () => {
		expect(taskLines(section(plan, "단계"))).toHaveLength(3);
		expect(section(plan, "Now")).toBe("- [ ] 바로 구현할 작업 1개 정의");
		expect(section(plan, "Done")).toBe("");
		expect(lines(section(plan, "Risks"))).toEqual(["- 없음"]);
		expect(section(plan, "검증 계획")).toBe("- [ ] 관련 스크립트 또는 테스트 실행");
	});

	it("does not confuse ### sub-sections with ## sections", () => {
		const goal = goalTemplate(STAMP);
		expect(section(goal, "Now")).toBe("");
		expect(subsection(goal, "Now")).toBe("- [ ] 목표 설명 작성");
		expect(subsection(goal, "Next")).toBe("- [ ] 첫 번째 작은 작업 선택");
		expect(subsection(goal, "Done")).toBe("");
	});

	it("returns empty strings for unknown sections", () => {
		expect(section(plan, "없는 섹션")).toBe("");
		expect(subsection(plan, "없는 섹션")).toBe("");
	});
});

describe("writeSection", () => {
	const plan = planTemplate("테스트 목표", "current-plan.md", STAMP);

	it("replaces a section body and keeps the rest intact", () => {
		const next = writeSection(plan, "Now", ["- [ ] A", "- [ ] B"]);
		expect(section(next, "Now")).toBe("- [ ] A\n- [ ] B");
		expect(section(next, "Next")).toBe(section(plan, "Next"));
		expect(headingTitle(next, "계획", "")).toBe("테스트 목표");
	});

	it("fills an empty section and can empty a filled one", () => {
		const filled = writeSection(plan, "Done", ["- [x] 완료"]);
		expect(section(filled, "Done")).toBe("- [x] 완료");
		expect(section(writeSection(filled, "Done", []), "Done")).toBe("");
	});

	it("leaves text unchanged when the section is missing", () => {
		expect(writeSection(plan, "없음", ["x"])).toBe(plan);
	});

	it("supports the advance flow end to end", () => {
		const now = taskLines(section(plan, "Now"));
		const next = taskLines(section(plan, "Next"));
		const done = lines(section(plan, "Done"));
		done.push("- [x] " + now.shift()!.replace(/^- \[ \] /, ""));
		now.push(next.shift()!);
		let text = writeSection(plan, "Now", now);
		text = writeSection(text, "Next", next);
		text = writeSection(text, "Done", done);
		expect(section(text, "Now")).toBe("- [ ] 뒤이어 실행할 작업 1개 정의");
		expect(section(text, "Next")).toBe("");
		expect(section(text, "Done")).toBe("- [x] 바로 구현할 작업 1개 정의");
	});
});

describe("sectionLines", () => {
	const plan = planTemplate("테스트 목표", "current-plan.md", STAMP);

	it("원본 줄을 들여쓰기까지 그대로 돌려주고 빈 섹션은 빈 배열이다", () => {
		const filled = writeSection(plan, "Now", ["- [ ] 상위", "  - [ ] 하위", "  참고: 들여쓴 메모"]);
		expect(sectionLines(filled, "Now")).toEqual(["- [ ] 상위", "  - [ ] 하위", "  참고: 들여쓴 메모"]);
		expect(sectionLines(plan, "Done")).toEqual([]);
		expect(sectionLines(plan, "없는 섹션")).toEqual([]);
	});
});

describe("moveTaskToSection", () => {
	const plan = planTemplate("테스트 목표", "current-plan.md", STAMP);
	const complete = (line: string) => line.replace(/^- \[ \]/, "- [x]");

	it("대상 섹션에 이미 있던 들여쓴 줄과 메모 줄을 보존한다", () => {
		const withDone = writeSection(plan, "Done", ["- [x] 지난 작업", "  - [x] 하위 완료", "  참고: 들여쓴 메모"]);
		const nowIndex = withDone.split("\n").indexOf("- [ ] 바로 구현할 작업 1개 정의");

		const moved = moveTaskToSection(withDone, nowIndex, "Done", complete);

		expect(moved).not.toBeNull();
		expect(section(moved!, "Done")).toBe(["- [x] 지난 작업", "  - [x] 하위 완료", "  참고: 들여쓴 메모", "- [x] 바로 구현할 작업 1개 정의"].join("\n"));
	});
});

describe("metadata lines", () => {
	const plan = planTemplate("테스트 목표", "current-plan.md", STAMP);

	it("reads and rewrites label lines", () => {
		expect(matchLine(plan, "상태")).toBe("draft");
		expect(matchLine(plan, "우선순위", "P2")).toBe("P2");
		const next = setLine(plan, "우선순위", "P0");
		expect(matchLine(next, "우선순위")).toBe("P0");
		expect(matchLine(setLine(next, "우선순위", "P1"), "우선순위")).toBe("P1");
		expect(next.indexOf("우선순위: P0")).toBeGreaterThan(next.indexOf("마지막 갱신:"));
	});

	it("touches status and timestamp", () => {
		const next = touchPlan(plan, "blocked", "2026-09-23 09:00:00 KST");
		expect(matchLine(next, "상태")).toBe("blocked");
		expect(matchLine(next, "마지막 갱신")).toBe("2026-09-23 09:00:00 KST");
		expect(matchLine(touchPlan(plan, null, "x"), "상태")).toBe("draft");
	});

	it("inserts a status line after the title when missing", () => {
		const text = "# 계획: x\n\n작성일: a\n\n## Now\n";
		const next = touchPlan(text, "active", "b");
		expect(next.startsWith("# 계획: x\n\n상태: active\n")).toBe(true);
		expect(matchLine(next, "마지막 갱신")).toBe("b");
	});

	it("escapes regex characters in labels", () => {
		expect(matchLine("a.b: 1\naxb: 2", "a.b")).toBe("1");
	});
});

describe("goal parsing", () => {
	it("summarizes the goal template", () => {
		const goal = parseGoal(goalTemplate(STAMP));
		expect(goal.title).toBe("새 목표");
		expect(goal.status).toBe("draft");
		expect(goal.phase).toBe("discovery");
		expect(goal.criteria).toHaveLength(3);
		expect(goal.now).toEqual(["- [ ] 목표 설명 작성"]);
		expect(goal.nextItems).toEqual(["- [ ] 첫 번째 작은 작업 선택"]);
		expect(goal.verification).toEqual([]);
		expect(countChecks(goalTemplate(STAMP))).toEqual({ done: 0, total: 5 });
	});
});

describe("CRLF 줄바꿈", () => {
	// Windows 체크아웃(core.autocrlf)이나 zip 왕복으로 `.vibe-code/*.md` 가 CRLF 가 되는 경로.
	const crlf = (text: string) => text.replace(/\n/g, "\r\n");
	const planLf = planTemplate("테스트 목표", "current-plan.md", STAMP);
	const planCrlf = crlf(planLf);
	const goalLf = goalTemplate(STAMP);
	const goalCrlf = crlf(goalLf);
	const nowTask = "- [ ] 바로 구현할 작업 1개 정의";
	const nowIndex = planLf.split("\n").indexOf(nowTask);
	const complete = (line: string) => line.replace(/^- \[ \]/, "- [x]");

	it("줄바꿈 방식을 첫 줄바꿈 기준으로 판정한다", () => {
		expect(detectEol(planLf)).toBe("\n");
		expect(detectEol(planCrlf)).toBe("\r\n");
		expect(detectEol("줄바꿈 없음")).toBe("\n");
		expect(detectEol("a\r\nb\nc")).toBe("\r\n");
		expect(detectEol("a\nb\r\nc")).toBe("\n");
		expect(normalizeEol(planCrlf)).toBe(planLf);
		expect(normalizeEol(planLf)).toBe(planLf);
	});

	it("읽기 함수가 CRLF 에서 LF 와 같은 값을 돌려준다", () => {
		for (const name of ["목표 정렬", "단계", "Now", "Next", "Done", "Risks", "검증 계획"]) {
			expect(section(planCrlf, name)).toBe(section(planLf, name));
			expect(section(planCrlf, name)).not.toMatch(/\r/);
			expect(hasSection(planCrlf, name)).toBe(true);
		}
		expect(section(planCrlf, "Now")).toBe(nowTask);
		expect(taskLines(section(planCrlf, "단계"))).toHaveLength(3);
		expect(hasSection(planCrlf, "없는 섹션")).toBe(false);
		for (const name of ["Now", "Next", "Done"]) expect(subsection(goalCrlf, name)).toBe(subsection(goalLf, name));
		expect(subsection(goalCrlf, "Now")).toBe("- [ ] 목표 설명 작성");
		expect(headingTitle(planCrlf, "계획", "")).toBe("테스트 목표");
		expect(matchLine(planCrlf, "상태")).toBe("draft");
		expect(countChecks(planCrlf)).toEqual(countChecks(planLf));
	});

	it("writeSection 이 CRLF 에서 같은 편집 결과를 내고 줄바꿈을 보존한다", () => {
		const next = writeSection(planCrlf, "Now", ["- [ ] A", "- [ ] B"]);
		expect(section(next, "Now")).toBe("- [ ] A\n- [ ] B");
		expect(next).toBe(crlf(writeSection(planLf, "Now", ["- [ ] A", "- [ ] B"])));
		expect(next).not.toMatch(/[^\r]\n/);
		expect(next).not.toMatch(/\r\r/);
	});

	it("moveTaskToSection 이 CRLF 에서 null 대신 옮긴 텍스트를 돌려준다", () => {
		const moved = moveTaskToSection(planCrlf, nowIndex, "Done", complete);
		expect(moved).not.toBeNull();
		expect(section(moved!, "Done")).toBe("- [x] 바로 구현할 작업 1개 정의");
		expect(section(moved!, "Now")).toBe("");
		expect(moved).toBe(crlf(moveTaskToSection(planLf, nowIndex, "Done", complete)!));
	});

	it("toggleCheckbox·touchPlan·setLine 이 입력의 줄바꿈을 보존한다", () => {
		expect(toggleCheckbox(planCrlf, nowIndex)).toBe(crlf(toggleCheckbox(planLf, nowIndex)));
		expect(touchPlan(planCrlf, "active", STAMP)).toBe(crlf(touchPlan(planLf, "active", STAMP)));
		expect(setLine(planCrlf, "우선순위", "P0")).toBe(crlf(setLine(planLf, "우선순위", "P0")));
		expect(touchPlan(planCrlf, "active", STAMP)).not.toMatch(/[^\r]\n/);
		expect(setLine(planCrlf, "우선순위", "P0")).not.toMatch(/[^\r]\n/);
	});

	it("계획·목표 소비자(parseGoal·openPlanItems)도 CRLF 에서 같은 값을 읽는다", () => {
		expect(parseGoal(goalCrlf)).toEqual(parseGoal(goalLf));
		expect(openPlanItems(planCrlf)).toEqual(openPlanItems(planLf));
		expect(openPlanItems(planCrlf)).toHaveLength(5);
	});

	it("린트가 CRLF 계획·목표에 섹션 누락 경고를 내지 않는다", () => {
		expect(lintPlan(planCrlf)).toEqual(lintPlan(planLf));
		expect(lintGoal(goalCrlf)).toEqual(lintGoal(goalLf));
		const missing = (issues: { message: string }[]) => issues.map((i) => i.message).filter((m) => m.includes("섹션이 없습니다"));
		expect(missing(lintPlan(planCrlf))).toEqual([]);
		expect(missing(lintGoal(goalCrlf))).toEqual([]);
	});
});

describe("priorityRank", () => {
	it("orders P0..P3 and pushes unknowns last", () => {
		expect(["P3", "p1", "P0", "zzz"].sort((a, b) => priorityRank(a) - priorityRank(b))).toEqual(["P0", "p1", "P3", "zzz"]);
		expect(priorityRank(undefined)).toBe(2);
		expect(priorityRank("")).toBe(2);
	});
});
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { advancePlanText, archiveDonePlans, conflictStamp, openPlanItems, planTemplate, selectPlanName } from "../../src/features/plans";
import type { WorkspacePaths } from "../../src/features/workspace";
import { matchLine, section, writeSection } from "../../src/util/markdown";

const temps: string[] = [];

function tempDir(): string {
	const dir = fs.mkdtempSync(path.join(os.tmpdir(), "vibe-plans-test-"));
	temps.push(dir);
	return fs.realpathSync(dir);
}

/** Real `.vibe-code/plans` + `plans/archive` directories — archiving is a filesystem contract, so nothing here is faked. */
function planDirs(): { plans: string; archive: string } {
	const plans = path.join(tempDir(), ".vibe-code", "plans");
	const archive = path.join(plans, "archive");
	fs.mkdirSync(archive, { recursive: true });
	return { plans, archive };
}

function plan(dir: string, name: string, status: string, body = ""): string {
	const file = path.join(dir, name);
	fs.writeFileSync(file, `# 계획: ${name}\n\n상태: ${status}\n${body}`, "utf8");
	return file;
}

function names(dir: string): string[] {
	return fs.readdirSync(dir).sort();
}

afterEach(() => {
	while (temps.length > 0) fs.rmSync(temps.pop() as string, { recursive: true, force: true });
});

describe("archiveDonePlans", () => {
	it("moves only done plans and leaves the rest of plans/ alone", () => {
		const { plans, archive } = planDirs();
		plan(plans, "done-plan.md", "done");
		plan(plans, "active-plan.md", "active");
		fs.writeFileSync(path.join(plans, ".active-plan"), "active-plan.md", "utf8");

		const archived = archiveDonePlans(plans, archive, "20260926070059");

		expect(archived).toEqual([{ name: "done-plan.md", dest: "done-plan.md" }]);
		expect(names(plans)).toEqual([".active-plan", "active-plan.md", "archive"]);
		expect(names(archive)).toEqual(["done-plan.md"]);
	});

	it("keeps the existing archived copy when a done plan reuses its name", () => {
		const { plans, archive } = planDirs();
		plan(archive, "current-plan.md", "done", "## 단계\n- [x] 지난 회차 작업\n");
		plan(plans, "current-plan.md", "done", "## 단계\n- [x] 이번 회차 작업\n");

		const archived = archiveDonePlans(plans, archive, "20260926070059");

		expect(fs.readFileSync(path.join(archive, "current-plan.md"), "utf8")).toContain("지난 회차 작업");
		expect(names(archive)).toEqual(["current-plan-20260926070059.md", "current-plan.md"]);
		expect(fs.readFileSync(path.join(archive, "current-plan-20260926070059.md"), "utf8")).toContain("이번 회차 작업");
		expect(archived).toEqual([{ name: "current-plan.md", dest: "current-plan-20260926070059.md" }]);
	});

	it("keeps both archived copies when the same name is archived twice within one stamp", () => {
		const { plans, archive } = planDirs();
		plan(archive, "current-plan.md", "done", "첫 번째\n");
		plan(archive, "current-plan-20260926070059.md", "done", "두 번째\n");
		plan(plans, "current-plan.md", "done", "세 번째\n");

		const archived = archiveDonePlans(plans, archive, "20260926070059");

		expect(archived[0].dest).toBe("current-plan-20260926070059-2.md");
		expect(names(archive)).toEqual(["current-plan-20260926070059-2.md", "current-plan-20260926070059.md", "current-plan.md"]);
		expect(fs.readFileSync(path.join(archive, "current-plan.md"), "utf8")).toContain("첫 번째");
		expect(fs.readFileSync(path.join(archive, "current-plan-20260926070059.md"), "utf8")).toContain("두 번째");
	});

	it("does not descend into the archive directory or touch non-markdown files", () => {
		const { plans, archive } = planDirs();
		plan(archive, "old.md", "done");
		fs.writeFileSync(path.join(plans, "notes.txt"), "상태: done\n", "utf8");

		expect(archiveDonePlans(plans, archive, "20260926070059")).toEqual([]);
		expect(names(archive)).toEqual(["old.md"]);
		expect(names(plans)).toEqual(["archive", "notes.txt"]);
	});

	it("creates the archive directory when it does not exist yet", () => {
		const plans = path.join(tempDir(), ".vibe-code", "plans");
		fs.mkdirSync(plans, { recursive: true });
		const archive = path.join(plans, "archive");
		plan(plans, "done-plan.md", "done");

		expect(archiveDonePlans(plans, archive, "20260926070059")).toEqual([{ name: "done-plan.md", dest: "done-plan.md" }]);
		expect(names(archive)).toEqual(["done-plan.md"]);
	});
});

describe("conflictStamp", () => {
	it("is 14 digits of Asia/Seoul time — the one format archive and restore both suffix with", () => {
		// 2026-09-25 22:01:02 UTC is 2026-09-26 07:01:02 KST.
		expect(conflictStamp(new Date("2026-09-25T22:01:02Z"))).toBe("20260926070102");
	});
});

describe("selectPlanName", () => {
	function paths(plans: string): WorkspacePaths {
		const base = path.dirname(plans);
		return {
			ws: path.dirname(base),
			base,
			goals: path.join(base, "goals"),
			sessions: path.join(base, "sessions"),
			checkpoints: path.join(base, "checkpoints"),
			plans,
			archive: path.join(plans, "archive"),
			journal: path.join(base, "journal"),
			audit: path.join(base, "audit"),
			current: path.join(base, "goals", "current.md"),
		};
	}

	it("follows the .active-plan pointer when it names an existing file", () => {
		const { plans } = planDirs();
		plan(plans, "a-plan.md", "active");
		plan(plans, "z-plan.md", "active");
		fs.writeFileSync(path.join(plans, ".active-plan"), "a-plan.md\n", "utf8");

		expect(selectPlanName(paths(plans))).toBe("a-plan.md");
	});

	it("falls back to the last file when the pointer names a file that is gone", () => {
		const { plans } = planDirs();
		plan(plans, "a-plan.md", "active");
		plan(plans, "z-plan.md", "active");
		fs.writeFileSync(path.join(plans, ".active-plan"), "archived-away.md", "utf8");

		expect(selectPlanName(paths(plans))).toBe("z-plan.md");
	});

	it("falls back to the default name for an empty plans directory", () => {
		const { plans } = planDirs();

		expect(selectPlanName(paths(plans))).toBe("current-plan.md");
	});
});

